-- Editorial teknik numaralarini temizler; kullanici basliklarini degistirmez.
update public.topics set title=regexp_replace(title,'\s+—\s+[0-9]+\s*$','','g') where is_editorial=true and title~'\s+—\s+[0-9]+\s*$';
update public.editorial_timed_pool set title=regexp_replace(title,'\s+—\s+[0-9]+\s*$','','g') where title~'\s+—\s+[0-9]+\s*$';
alter table public.topics add column if not exists normalized_editorial_title text generated always as(case when is_editorial then lower(regexp_replace(regexp_replace(trim(title),'\s+—\s+[0-9]+\s*$','','g'),'[^[:alnum:]]','','g')) else null end) stored;
create table if not exists public.editorial_duplicate_audit(id bigint generated always as identity primary key,normalized_title text not null,canonical_topic_id uuid not null,duplicate_topic_id uuid not null,real_answer_count integer not null,action text not null,created_at timestamptz not null default now(),unique(duplicate_topic_id));
with ranked as(select t.id,t.normalized_editorial_title,row_number()over(partition by t.normalized_editorial_title order by (select count(*) from answers a where a.topic_id=t.id and not a.is_editorial)desc,t.view_count desc,t.created_at asc)rn from topics t where t.is_editorial and t.normalized_editorial_title is not null),pairs as(select d.id duplicate_id,c.id canonical_id,d.normalized_editorial_title,(select count(*) from answers a where a.topic_id=d.id and not a.is_editorial)real_count from ranked d join ranked c on c.normalized_editorial_title=d.normalized_editorial_title and c.rn=1 where d.rn>1) insert into editorial_duplicate_audit(normalized_title,canonical_topic_id,duplicate_topic_id,real_answer_count,action) select normalized_editorial_title,canonical_id,duplicate_id,real_count,case when real_count=0 then 'safe_merge' else 'manual_review_preserved' end from pairs on conflict(duplicate_topic_id)do update set canonical_topic_id=excluded.canonical_topic_id,real_answer_count=excluded.real_answer_count,action=excluded.action;
-- Yalniz gercek kullanici cevabi olmayan tekrarlar transaction icinde birlestirilir.
update answers a set topic_id=r.canonical_topic_id from editorial_duplicate_audit r where a.topic_id=r.duplicate_topic_id and r.action='safe_merge' and a.is_editorial and not exists(select 1 from answers x where x.topic_id=r.canonical_topic_id and x.editorial_key=a.editorial_key);
delete from answers a using editorial_duplicate_audit r where a.topic_id=r.duplicate_topic_id and r.action='safe_merge' and a.is_editorial;
delete from topics t using editorial_duplicate_audit r where t.id=r.duplicate_topic_id and r.action='safe_merge';
-- Gercek cevapli duplicate korunabilecegi icin zorlayici unique index kurulmaz.
create index if not exists editorial_normalized_title_idx on public.topics(normalized_editorial_title) where is_editorial and normalized_editorial_title is not null;
update public.platform_settings set value=jsonb_set(value,'{reuse_after_days}','90'::jsonb),updated_at=now() where key='editorial_timed_topics';
-- Havuz kimligi public basliktan ayridir; gorseller kontrollu kategorilere atanir.
update public.editorial_timed_pool set title=regexp_replace(title,'\s+—\s+[0-9]+\s*$','','g');
update public.topics set image_url='/editorial/futbol/tribun-atmosferi.png' where is_editorial and image_url is null and category_id=(select id from categories where slug='futbol') and editorial_key in('futbol-01','futbol-03');
update public.topics set image_url='/editorial/otomobil/ikinci-el-inceleme.png' where is_editorial and image_url is null and category_id=(select id from categories where slug='otomobil-motosiklet') and editorial_key in('otomobil-01','otomobil-05');
create or replace function public.refill_editorial_timed_topics() returns integer language plpgsql security definer set search_path=public as $$declare cfg jsonb;needed int;item record;topic_uuid uuid;hours int;created int:=0;last_cat text;begin select value into cfg from platform_settings where key='editorial_timed_topics';if not coalesce((cfg->>'enabled')::boolean,false)then return 0;end if;select c.slug into last_cat from topics t join categories c on c.id=t.category_id where t.is_editorial and t.is_timed order by t.created_at desc limit 1;needed=greatest(0,coalesce((cfg->>'target_active')::int,3)-(select count(*)from topics where is_editorial and is_timed and status='published' and expires_at>now()));for item in select p.* from editorial_timed_pool p where p.is_active and p.category_slug is distinct from last_cat and(p.last_used_at is null or p.last_used_at<now()-interval'90 days')and not exists(select 1 from topics t where t.is_editorial and t.editorial_key like p.editorial_key||'-%' and t.created_at>now()-interval'90 days')order by p.last_used_at nulls first,random()limit needed loop hours=(array[24,48,72])[1+floor(random()*3)::int];insert into topics(user_id,category_id,title,body,slug,audience,status,is_editorial,editorial_key,editorial_label,is_timed,timed_duration_hours,expires_at,image_url)select null,c.id,item.title,item.body,item.editorial_key||'-'||to_char(now(),'YYYYMMDDHH24MI'),case when item.category_slug='kadinlara-sor'then'female'when item.category_slug='erkeklere-sor'then'male'else'all'end,'published',true,item.editorial_key||'-'||to_char(now(),'YYYYMMDDHH24MI'),'ANLATI Editör',true,hours,now()+make_interval(hours=>hours),case when item.category_slug='futbol'then'/editorial/futbol/tribun-atmosferi.png'when item.category_slug='otomobil-motosiklet'then'/editorial/otomobil/ikinci-el-inceleme.png'else null end from categories c where c.slug=item.category_slug returning id into topic_uuid;insert into answers(topic_id,user_id,body,status,is_editorial,editorial_key,editorial_label)values(topic_uuid,null,item.answer_one,'published',true,item.editorial_key||'-'||topic_uuid||'-a1','ANLATI Editör'),(topic_uuid,null,item.answer_two,'published',true,item.editorial_key||'-'||topic_uuid||'-a2','ANLATI Editör');update editorial_timed_pool set last_used_at=now()where id=item.id;last_cat=item.category_slug;created=created+1;end loop;return created;end;$$;
